// Aufbereitung der Fehlermeldung von n8n (Error Trigger)
const j = $json;
const ex = j.execution || {};
const wf = j.workflow || {};
const stelle = ex.lastNodeExecuted || (j.trigger ? 'Auslöser' : 'unbekannt');
const fehler = String((ex.error && ex.error.message) || (j.trigger && j.trigger.error && j.trigger.error.message) || 'ohne Fehlertext').slice(0, 400);
const bloecke = [
  { titel: 'Ablauf', inhalt: wf.name || wf.id || 'unbekannt' },
  { titel: 'Stelle', inhalt: stelle },
  { titel: 'Fehler', inhalt: fehler },
];
if (ex.url) bloecke.push({ titel: 'Ausführung', inhalt: ex.url });
return { json: {
  schluessel: 'ablauf:' + (wf.id || '?') + ':' + stelle,
  // Migration 179 (P6): Auslöser-Fehler (ohne Ausführung) eines Postfach-Workflows prüft 7_10 gegen die Postfach-Liste
  ausloeser_wf: (!ex.id && !ex.lastNodeExecuted && j.trigger) ? String(wf.id || '') : '',
  fehler,
  titel: 'Ablauf abgebrochen',
  bloecke,
  test: false
} };

// Meldung eines Ablaufs übernehmen; test = true heißt: nur Vorschau, nichts senden
const j = $json;
const bloecke = [];
if (j.ablauf) bloecke.push({ titel: 'Ablauf', inhalt: String(j.ablauf) });
bloecke.push({ titel: 'Was passiert ist', inhalt: String(j.text || '').slice(0, 1500) });
return { json: {
  schluessel: String(j.schluessel || ('meldung:' + (j.ablauf || '?'))),
  titel: String(j.titel || 'Meldung'),
  bloecke,
  test: j.test !== false
} };

// Eine Nachricht je Empfänger. Layout: Titel fett mit Doppelpunkt, Inhalt darunter, Leerzeile zwischen Blöcken, keine Emojis
const quelle = $('7_4 Meldung übernehmen').isExecuted ? $('7_4 Meldung übernehmen').all() : $('7_2 Fehler aufbereiten').all();
const aus = [];
$input.all().forEach((it, i) => {
const r = it.json.r || {};
const vorher = (quelle[i] || quelle[0]).json;
const ohneEmoji = s => String(s ?? '').replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '');
const esc = s => ohneEmoji(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const zeit = $now.setZone('Europe/Berlin').toFormat('dd.MM.yyyy, HH:mm');
const bloecke = [...(vorher.bloecke || []), { titel: 'Zeit', inhalt: zeit }];
if (r.unterdrueckt > 0) bloecke.push({ titel: 'Hinweis', inhalt: 'Dieselbe Meldung kam seit der letzten Nachricht ' + r.unterdrueckt + ' weitere Male.' });
const text = ohneEmoji(vorher.titel) + ':\n\n' + bloecke.map(b => ohneEmoji(b.titel) + ':\n' + ohneEmoji(b.inhalt)).join('\n\n');
const html = '<strong>' + esc(vorher.titel) + ':</strong><br><br>' + bloecke.map(b => '<strong>' + esc(b.titel) + ':</strong><br>' + esc(b.inhalt).split('\n').join('<br>')).join('<br><br>');
const test = vorher.test === true || $execution.mode === 'test';
const empfaenger = Array.isArray(r.empfaenger) ? r.empfaenger : [];
if (!empfaenger.length) { aus.push({ json: { senden: false, test, grund: r.gedrosselt ? 'gedrosselt' : 'kein Empfänger', text, html } }); return; }
empfaenger.forEach(e => aus.push({ json: { senden: r.senden === true && !test, test, user_id: e.user_id, room_id: e.room_id, text, html } }));
});
return aus;

