-- Benachrichtigung in der Oberfläche zur gesendeten Meldung (BA4, Stefan 20.10.2026), Art systemfehler, gleiche Person wie im Chat.
-- Drosselung und Empfänger kommen aus 7_5; Testläufe erreichen diesen Zweig nicht. Wirft nie einen Fehler; das Senden läuft unabhängig davon.
SELECT ally_benachrichtigung_aus_chat($1::text, 'systemfehler', NULL, NULL, NULL, 'SYS 7') AS r;

-- Migration 179 (P6): Auslöser-Fehler eines eingerichteten Postfachs wird als Störung eingetragen (MAIL 6 startet neu und meldet nach 3 Versuchen);
-- sonst und bei jedem Fehler hier meldet SYS 7 wie bisher. Testläufe tragen nichts ein.
SELECT postfach_empfang_fehler($1::text, $2::text, $3::boolean) AS r;

